entries.syntax_block:
Reader = New TextReader(path, TextEncoding.UTF8);

Line = Reader.ReadLine();
while (Line <> Undefined) {        // Undefined, not "": an empty line is a line
    Line = Reader.ReadLine();
}
Reader.Close();

entries.syntax_block_ves:
Reader = New TextReader(path, TextEncoding.UTF8);

Line = Reader.ReadLine();
While Line <> Undefined Do        // Undefined, not "": an empty line is a line
    Line = Reader.ReadLine();
EndDo;
Reader.Close();

entries.example:
Reader = New TextReader("C:\in\sales.csv", TextEncoding.UTF8);
Line = Reader.ReadLine();
while (Line <> Undefined) {              // Undefined, а не "": пустая строка — это строка
    if (Line <> "") {
        Cut = Find(Line, ";");
        Code = Left(Line, Cut - 1);      // первое поле
    }
    Line = Reader.ReadLine();
}
Reader.Close();

Reader = New TextReader(first);
Message(Reader.ReadLine());
Reader.Open(second);          // первый файл отпущен; читатель стоит на строке 1 второго
Message(Reader.ReadLine());
Reader.Close();

Line = Reader.ReadLine();
while (Line <> Undefined) {       // а не while (Line <> "")
    Message(Line);
    Line = Reader.ReadLine();
}

Header = Reader.ReadLine();       // первая строка отдельно
Body = Reader.Read();             // всё, что после неё, вместе с переводами строк
Reader.Close();

Reader = New TextReader(path);
for (n = 1 To Reader.LineCount()) {
    Message(Reader.GetLine(n));
}
Reader.Close();

Reader = New TextReader(path);
Message(Reader.GetLine(1));                    // строка заголовка
Message(Reader.GetLine(Reader.LineCount()));   // последняя
Message(Reader.ReadLine());                    // по-прежнему строка 1: GetLine её не сдвинул
Reader.Close();

entries.syntax_block:
Writer = New TextWriter(path, TextEncoding.UTF8);
Writer = New TextWriter(path, TextEncoding.UTF8, True);   // append instead of replace

Writer.WriteLine("code;name;qty");
Writer.Write("00001;Paper;12");
Writer.Close();                                           // here, and only here, a failure is told

entries.example:
Writer = New TextWriter(GetTempDir() + "sales.csv", TextEncoding.UTF8);
Writer.WriteLine("code;name;qty");
Writer.WriteLine("00001;Бумага;12");
Writer.Close();                      // выгрузка цела только после того, как это вернулось

Writer = New TextWriter(first);
Writer.WriteLine("one");
Writer.Open(second);          // первый файл ЗАКРЫВАЕТСЯ здесь — и о неудавшемся закрытии скажут здесь
Writer.WriteLine("two");
Writer.Close();

Writer.Write("00001;");
Writer.Write("Бумага;");
Writer.WriteLine("12");        // перевод строки, который заканчивает строку файла

try {
    Writer.Close();
} except {
    Message("выгрузка не дошла до диска: " + ErrorDescription());
}

